const int DISTANCE_SENSOR_PIN = A0; // Mesafe sensörü pini tanımlandı.

void setup() {
    setIOpins();
    pinMode(DISTANCE_SENSOR_PIN, INPUT);
}

void loop() {
    int distance = analogRead(DISTANCE_SENSOR_PIN); // Mesafe sensöründen okuma yap
    if (distance < THRESHOLD) { // THRESHOLD, uygun eşik değeri
        stopTheRobot();
        delay(500); // Bir süre bekleyin
        turnRight(); // Sağ döndür
    } else {
        moveForward(); // Dönmediği sürece ileri git
    }
}
```

